@sig trait Priority_Arbitration_Api {
  def id: Art.BridgeId
  def emergency_state_Id : Art.PortId
  def mining_proposal_Id : Art.PortId
  def defense_proposal_Id : Art.PortId
  def mobility_proposal_Id : Art.PortId
  def selected_action_Id : Art.PortId
  def selected_cause_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var selected_action: Mining_Threat_Retreat_Supervision.ActionValue = $

  def put_selected_action(value : Mining_Threat_Retreat_Supervision.ActionValue) : Unit = {
    Contract(
      Modifies(selected_action),
      Ensures(
        selected_action == value
      )
    )
    Spec {
      selected_action = value
    }

    Art.putValue(selected_action_Id, Mining_Threat_Retreat_Supervision.ActionValue_Payload(value))
  }

  // Logika spec var representing port state for outgoing data port
  @spec var selected_cause: Mining_Threat_Retreat_Supervision.SelectedCauseValue = $

  def put_selected_cause(value : Mining_Threat_Retreat_Supervision.SelectedCauseValue) : Unit = {
    Contract(
      Modifies(selected_cause),
      Ensures(
        selected_cause == value
      )
    )
    Spec {
      selected_cause = value
    }

    Art.putValue(selected_cause_Id, Mining_Threat_Retreat_Supervision.SelectedCauseValue_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

